mapper.select:
SELECT a.QUESTION_ID, a.QUESTION_CONTENT, a.QUESTION_OPINIONS, e.RULE_FILE_NAME, e.RULE_FILE_NO, e.RULE_FILE_CONTENT, l.ID, l.IS_SCHEME, l.IS_CASE, l.IS_COMPLETE, l.COMPLETE_TIME FROM inspection.`inspection_question_ledger_postsv` a JOIN `inspection`.inspection_reform_ledger_postsv l ON a.LEDGER_ID = l.LEDGER_ID LEFT JOIN `inspection`.inspection_question_ledger_rule_postsv e ON a.`LEDGER_ID` = e.LEDGER_ID WHERE 1=1
AND a.TASK_ID = #{params.TASK_ID}
AND a.IS_LIST = #{params.IS_LIST}
AND l.IS_CASE = #{params.IS_CASE}
ORDER BY a.ADD_DATE desc

SELECT count(1) FROM inspection.`inspection_question_ledger_postsv` a JOIN `inspection`.inspection_reform_ledger_postsv l ON a.LEDGER_ID = l.LEDGER_ID LEFT JOIN `inspection`.inspection_question_ledger_rule_postsv e ON a.`LEDGER_ID` = e.LEDGER_ID WHERE 1=1 AND a.IS_REPORT = '0'
AND a.TASK_ID = #{params.TASK_ID}
AND a.IS_LIST = #{params.IS_LIST}
AND l.IS_CASE = #{params.IS_CASE}
ORDER BY a.ADD_DATE desc LIMIT ${params.page},${params.rows}

SELECT a.QUESTION_ID, a.QUESTION_CONTENT, a.QUESTION_OPINIONS, e.RULE_FILE_NAME, e.RULE_FILE_NO, e.RULE_FILE_CONTENT, l.ID, l.IS_SCHEME, l.IS_CASE, l.IS_COMPLETE, l.COMPLETE_TIME FROM inspection.`inspection_question_ledger_postsv` a JOIN `inspection`.inspection_reform_ledger_postsv l ON a.LEDGER_ID = l.LEDGER_ID LEFT JOIN `inspection`.inspection_question_ledger_rule_postsv e ON a.`LEDGER_ID` = e.LEDGER_ID WHERE 1=1 AND a.IS_REPORT = '0'
AND a.TASK_ID = #{params.TASK_ID}
AND a.IS_LIST = #{params.IS_LIST}
AND l.IS_CASE = #{params.IS_CASE}
AND l.LEDGER_ID = #{params.LEDGER_ID}
ORDER BY a.ADD_DATE desc

SELECT a.*, c.NAME AS USER_NAME FROM inspection.inspection_reform_scheme_postsv a LEFT JOIN inspection.inspection_sysuser_talentpool_relation b on a.USER = b.SYS_USERID LEFT JOIN inspection.cm_guoku_talentpool c on b.TALENTPOOL_ID = c.UUID WHERE 1 = 1
AND a.ID = #{params.ID}
AND a.REFORM_ID = #{params.REFORM_ID}
ORDER BY a.SCHEME_TIME asc

SELECT a.*, c.NAME AS USER_NAME FROM inspection.inspection_reform_replay_postsv a LEFT JOIN inspection.inspection_sysuser_talentpool_relation b on a.REPLY_USER = b.SYS_USERID LEFT JOIN inspection.cm_guoku_talentpool c on b.TALENTPOOL_ID = c.UUID WHERE 1=1
AND a.ID = #{params.ID}
AND a.SCHEME_ID = #{params.SCHEME_ID}
ORDER BY a.REPLY_TIME asc

SELECT a.QUESTION_ID_1, a.QUESTION_ID_2, a.QUESTION_DSCR AS QUESTION_DSCR_1, a.QUESTION_DSCR AS QUESTION_DSCR_2 FROM inspection.`inspection_question_ledger_postsv` a WHERE
a.`QUESTION_DSCR_3` <> '其他'
a.`QUESTION_DSCR_3` = '其他'
AND a.`TASK_ID` = #{params.TASK_ID}
AND a.ADD_USERID = #{params.ADD_USERID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.IS_LIST = #{params.IS_LIST}
GROUP BY a.QUESTION_ID_1, a.QUESTION_ID_2 ORDER BY a.ADD_DATE

SELECT a.QUESTION_ID_1, a.QUESTION_DSCR AS QUESTION_DSCR_1 FROM inspection.`inspection_question_ledger_postsv` a WHERE
a.`QUESTION_DSCR_3` <> '其他'
a.`QUESTION_DSCR_3` = '其他'
AND a.`TASK_ID` = #{params.TASK_ID}
AND a.ADD_USERID = #{params.ADD_USERID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.IS_LIST = #{params.IS_LIST}
GROUP BY a.QUESTION_ID_1 ORDER BY a.ADD_DATE
